package compiler

import (
	"bytes"
	"fmt"
	"strings"
	"text/template"
)

const bashTemplate = `#!/usr/bin/env bash
# Auto-generated by runforge Trajectory Compiler
# Workflow: {{ .Name }}
# Estimated Token Savings: {{ printf "%.1f" .Metadata.EstimatedSavingsPct }}%

set -euo pipefail

echo "=================================================="
echo "Starting deterministic workflow: {{ .Name }}"
echo "=================================================="

{{ range .Steps }}
echo "--> Executing: {{ .Name }}"
{{ if .RequiresApproval }}
read -p "Warning: This step requires confirmation ({{ .Run }}). Proceed? [y/N] " confirm
if [[ "$confirm" != [yY] && "$confirm" != [yY][eE][sS] ]]; then
    echo "Aborted by user."
    exit 1
fi
{{ end }}
{{ if .Run }}
{{ .Run }}
{{ end }}
{{ end }}

echo "=================================================="
echo "Workflow completed successfully with 0 tokens spent."
echo "=================================================="
`

const psTemplate = `# Auto-generated by runforge Trajectory Compiler
# Workflow: {{ .Name }}
# Estimated Token Savings: {{ printf "%.1f" .Metadata.EstimatedSavingsPct }}%

$ErrorActionPreference = "Stop"

Write-Host "==================================================" -ForegroundColor Cyan
Write-Host "Starting deterministic workflow: {{ .Name }}" -ForegroundColor Cyan
Write-Host "==================================================" -ForegroundColor Cyan

{{ range .Steps }}
Write-Host "--> Executing: {{ .Name }}" -ForegroundColor Yellow
{{ if .RequiresApproval }}
$confirm = Read-Host "Warning: Step requires confirmation ({{ .Run }}). Proceed? (y/n)"
if ($confirm -ne 'y') {
    Write-Error "Execution canceled by user."
    exit 1
}
{{ end }}
{{ if .Run }}
Invoke-Expression "{{ .Run }}"
{{ end }}
{{ end }}

Write-Host "==================================================" -ForegroundColor Green
Write-Host "Workflow completed successfully with 0 tokens spent." -ForegroundColor Green
Write-Host "==================================================" -ForegroundColor Green
`

const pythonTemplate = `#!/usr/bin/env python3
"""
Auto-generated by runforge Trajectory Compiler
Workflow: {{ .Name }}
Estimated Token Savings: {{ printf "%.1f" .Metadata.EstimatedSavingsPct }}%
"""

import subprocess
import sys

def main():
    print("=" * 50)
    print("Starting deterministic workflow: {{ .Name }}")
    print("=" * 50)

{{ range .Steps }}
    print("--> Executing: {{ .Name }}")
{{ if .RequiresApproval }}
    ans = input("Warning: Step requires confirmation ({{ .Run }}). Proceed? [y/N]: ")
    if ans.strip().lower() not in ("y", "yes"):
        print("Execution aborted.")
        sys.exit(1)
{{ end }}
{{ if .Run }}
    res = subprocess.run({{ printf "%q" .Run }}, shell=True, text=True)
    if res.returncode != 0:
        print(f"Error: Step '{{ .Name }}' failed with exit code {res.returncode}")
        sys.exit(res.returncode)
{{ end }}
{{ end }}

    print("=" * 50)
    print("Workflow completed successfully with 0 tokens spent.")
    print("=" * 50)

if __name__ == "__main__":
    main()
`

// GenerateBash generates a self-contained Bash script.
func GenerateBash(playbook *Playbook) (string, error) {
	tmpl, err := template.New("bash").Parse(bashTemplate)
	if err != nil {
		return "", err
	}
	var buf bytes.Buffer
	if err := tmpl.Execute(&buf, playbook); err != nil {
		return "", err
	}
	return buf.String(), nil
}

// GeneratePowerShell generates a self-contained PowerShell script.
func GeneratePowerShell(playbook *Playbook) (string, error) {
	tmpl, err := template.New("ps").Parse(psTemplate)
	if err != nil {
		return "", err
	}
	var buf bytes.Buffer
	if err := tmpl.Execute(&buf, playbook); err != nil {
		return "", err
	}
	return buf.String(), nil
}

// GeneratePython generates a self-contained Python script.
func GeneratePython(playbook *Playbook) (string, error) {
	tmpl, err := template.New("py").Parse(pythonTemplate)
	if err != nil {
		return "", err
	}
	var buf bytes.Buffer
	if err := tmpl.Execute(&buf, playbook); err != nil {
		return "", err
	}
	return buf.String(), nil
}

// GenerateScript emits code in the requested format ("bash", "powershell", "python").
func GenerateScript(playbook *Playbook, format string) (string, error) {
	switch strings.ToLower(format) {
	case "bash", "sh":
		return GenerateBash(playbook)
	case "powershell", "ps1", "ps":
		return GeneratePowerShell(playbook)
	case "python", "py":
		return GeneratePython(playbook)
	default:
		return "", fmt.Errorf("unsupported script format: %s", format)
	}
}
